import sys,glob,os,re
sys.path.insert(0,'/tmp/ut-m4')
import integrate_staging as S
dest=lambda p: open(p,encoding='utf-8').read()
spec=dest('/tmp/ut-m4/dest/SPEC.md'); bl=dest('/tmp/ut-m4/dest/BACKLOG.md'); rd=dest('/tmp/ut-m4/dest/readiness.md')
dec={os.path.basename(p)[:5]:dest(p) for p in glob.glob('/tmp/ut-m4/dest/decisions/D-*.md')}
norm=lambda s: re.sub(r'\s+',' ',s)
rep=norm(rd)
tot={}; miss=[]
for path in sorted(glob.glob('/tmp/ut-m4/stg/reports/staging/*.md')):
    feat=os.path.basename(path)[:-3]
    sec=S.parse(path)
    for key in (S.SPEC,S.BACKLOG,S.DECISIONS,S.DEFERRED,S.LIBRARY):
        items,paras=S.items_and_paragraphs(sec.get(key,[]))
        for text,cells in items:
            if key==S.SPEC: body=S.NEW_ROW.sub('',text); target=norm(spec)
            elif key==S.BACKLOG:
                if S.CLOSURE.match(text): body=text; target=norm(bl)+rep
                else:
                    item,_=(cells[0],None) if cells is not None else S.split_backlog(S.NEW_BACKLOG.sub('',text),feat); body=item; target=norm(bl)
            elif key==S.DECISIONS:
                ref=S.DECISION_REF.search(text)
                body=S.DECISION_PREFIX.sub('',text).strip().strip('"') or text
                target=norm(dec.get('D-'+ref.group(1),'')) if ref and not S.NOT_AN_AMENDMENT.search(text) else rep
            else: body=text; target=rep
            body=norm(body)
            # cell() escapes pipes in table rows
            probe=body[:40]; ok = probe in target or probe.replace('|','\\|') in target
            k=(key,); t=tot.setdefault(key,[0,0]); t[0]+=1; t[1]+=ok
            if not ok: miss.append((feat,key,probe))
print('section: [rows, found]'); 
for k,v in tot.items(): print(k,v)
print('missing',len(miss))
for m in miss: print(m)
EOF
python3 /tmp/ut-m4/check_rows.py | tee $E/tool-006-staging-row-grep.txt

